#!/usr/bin/env python3
"""Build roqsim's Bitcraze Crazyflie 2 MJCF from MuJoCo Menagerie's ``bitcraze_crazyflie_2``.

Like the xArm 7 converter, this *transforms* a curated upstream model rather than authoring one:
the mass, diagonal inertia, actuator gears, IMU sensors and the 32-piece convex collision
decomposition are all Menagerie's, passed through unchanged. Re-running against the pinned commit
must reproduce the committed file byte for byte, which ``--check`` asserts.

Five deltas. Four are roqsim conventions; the fifth is a tuning upstream asks for:

1. **No ``<option>``.** Upstream pins ``integrator="RK4" density="1.225" viscosity="1.8e-5"``. That
   is world-scoped physics: a model carrying it would silently reconfigure every world it is spawned
   into. Unlike an arm's integrator preference the medium terms are *load-bearing* -- MuJoCo defaults
   both to 0, so a world that does not ask for air flies this drone through a vacuum -- which is why
   moving them out required adding the world's ``density``/``viscosity`` to the world config rather than just deleting
   them. ``crazyflie_2_demo.yaml`` shows the block every aerial world needs.
2. **Body pose neutralised.** Upstream spawns the body at ``z=0.1`` for its own ``scene.xml``;
   ``spawn_robot`` places the drone from the world, and the ``hover`` keyframe still carries the
   0.1 m reference height in ``qpos``.
3. **Renamed** ``cf2`` -> ``crazyflie_2``, so the model short name that ``spawn_robot`` resolves
   matches the ledger key and the package's other conventions.
4. **The free joint is named ``base_free``.** Upstream's ``<freejoint/>`` is anonymous, and
   ``spawn_robot`` places, resets and teleports an entity through the joint it knows by that name --
   every wheeled base, the humanoids and Spot all carry it. Without the name the drone spawns at the
   model origin whatever the world asked for, does not return there on reset, and
   ``simulation_interfaces``' ``SetEntityState`` refuses it.

5. **The body-moment gears are set from the airframe.** Upstream's README says plainly that "the
   ``ctrlrange`` limits are currently arbitrary and need to be further tuned", and the arbitrary
   value is 1e-5 N*m -- against a body inertia of 2.4e-5 kg*m^2 that is 0.42 rad/s^2 of angular
   acceleration at full deflection, i.e. one second to tilt 12 degrees. Measured, not assumed: a
   drone with that authority hovers perfectly and cannot translate, because no attitude loop can
   track a position controller's tilt command. So the gears are derived from the real airframe
   instead, which is the tuning upstream is asking for rather than a disagreement with it:

     roll/pitch  2 rotors x 0.066 N differential x 0.0325 m effective X-arm  = 4.3e-3 N*m
     yaw         rotor drag, k_M/k_F ~ 0.006 m x 0.13 N total differential  = 8.0e-4 N*m

   (0.066 N is the per-rotor hover thrust, 0.027 kg * 9.81 / 4, so the differential is what the
   rotors can actually give up or add about hover; 0.0325 m is the 92 mm motor-to-motor diagonal
   resolved for an X configuration.) The collective-thrust range is left at upstream's [0, 0.35] N,
   which is a thrust-to-weight of 1.32 -- low for a Crazyflie but not disabling, and noted in the
   port log rather than changed.

The collision geometry is deliberately NOT touched. Upstream already ships a 32-piece convex
decomposition of the airframe, which is exactly what the porting playbook asks for -- the xArm's
fitted primitives existed only because Menagerie shipped none for that arm.

Usage::

    python external/convert/build_crazyflie_2_mjcf.py           # fetch, build, write
    python external/convert/build_crazyflie_2_mjcf.py --check   # rebuild and diff
"""

from __future__ import annotations

import argparse
import shutil
import sys
import xml.etree.ElementTree as ET
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
from sources import resolve_source  # noqa: E402

MENAGERIE_URL = "https://github.com/google-deepmind/mujoco_menagerie.git"
# Pinned; the port log and README licence table move with it.
MENAGERIE_COMMIT = "da76818e269b82289eba39808e2fb91d679d6994"
MENAGERIE_SUBDIR = "bitcraze_crazyflie_2"

PKG = (
    Path(__file__).resolve().parents[2]
    / "roqsim_aerial/src/roqsim_aerial/models/crazyflie_2"
)

MESHES = [f"cf2_{i}.obj" for i in range(7)] + [f"cf2_collision_{i}.obj" for i in range(32)]

#: Delta 5 -- see the docstring. Magnitudes only; upstream's negative sign is preserved.
MOMENT_GEARS = {"x_moment": 4.3e-3, "y_moment": 4.3e-3, "z_moment": 8.0e-4}

HEADER = f"""<mujoco model="crazyflie_2">
  <!--
    Bitcraze Crazyflie 2 (nano quadrotor) for MuJoCo.

    GENERATED by external/convert/build_crazyflie_2_mjcf.py from MuJoCo Menagerie's
    `bitcraze_crazyflie_2` @ {MENAGERIE_COMMIT} (MIT - see CRAZYFLIE_2_LICENSE).
    Do not hand-edit: re-run the generator. Mass, inertia, actuator gears, the IMU sensors and the
    32-piece convex collision decomposition are Menagerie's own values, passed through unchanged.

    Actuation is collective thrust plus three body moments, not four rotor speeds - the standard
    quadrotor control abstraction. `body_thrust` is a force in newtons (hover = 0.027 kg * 9.81 =
    0.265 N); the three moment actuators carry a NEGATIVE gear, so a positive ctrl produces a
    negative body moment. `quadrotor_controller` handles that sign.

    Four documented deltas (the generator's docstring says why):
      1. no <option> - integrator AND the medium terms belong to the world's `density`/`viscosity`. Note
         this one matters: MuJoCo defaults density/viscosity to 0, so a world that does not ask
         for air flies this drone through a vacuum.
      2. body pose neutralised to the origin - spawn_robot places it; the hover keyframe keeps 0.1 m
      3. renamed cf2 -> crazyflie_2
      4. the free joint is named base_free, the substrate-wide name spawn_robot places and resets
         through; upstream's is anonymous
      5. body-moment gears set from the airframe (roll/pitch 4.3e-3, yaw 8.0e-4 N*m). Upstream's
         README calls its 1e-5 arbitrary and asks for tuning; at 1e-5 the drone cannot translate
         at all. Derivation in the generator docstring.
  -->
"""


def build(source: Path) -> str:
    tree = ET.parse(source / "cf2.xml")
    root = tree.getroot()
    root.set("model", "crazyflie_2")
    root.find("compiler").set("meshdir", "meshes")
    for option in root.findall("option"):
        root.remove(option)
    body = root.find('worldbody/body[@name="cf2"]')
    body.set("pos", "0 0 0")
    body.find("freejoint").set("name", "base_free")
    for name, moment in MOMENT_GEARS.items():
        actuator = root.find(f'actuator/motor[@name="{name}"]')
        axis = "xyz".index(name[0]) + 3
        gear = actuator.get("gear").split()
        # Keep upstream's sign convention (negative), replace only the magnitude.
        gear[axis] = f"{-abs(moment):g}"
        actuator.set("gear", " ".join(gear))
    ET.indent(tree, space="  ")
    xml = ET.tostring(root, encoding="unicode")
    return HEADER + xml[xml.index(">") + 1:].lstrip("\n")


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__,
                                     formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()

    source = resolve_source("mujoco_menagerie", MENAGERIE_URL, MENAGERIE_COMMIT,
                            sparse=MENAGERIE_SUBDIR, subdir=MENAGERIE_SUBDIR)
    xml = build(source)
    target = PKG / "crazyflie_2.xml"

    if args.check:
        if not target.exists() or target.read_text() != xml:
            print(f"{target} differs from a fresh build - was it hand-edited?", file=sys.stderr)
            return 1
        print(f"{target}: up to date with {MENAGERIE_COMMIT[:12]}")
        return 0

    (PKG / "meshes").mkdir(parents=True, exist_ok=True)
    for mesh in MESHES:
        shutil.copy2(source / "assets" / mesh, PKG / "meshes" / mesh)
    shutil.copy2(source / "LICENSE", PKG / "CRAZYFLIE_2_LICENSE")
    target.write_text(xml)
    print(f"wrote {target} + {len(MESHES)} meshes + CRAZYFLIE_2_LICENSE")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
